async function main() {
  const bot = createBot();

  process.once("SIGINT", () => bot.stop("SIGINT"));
  process.once("SIGTERM", () => bot.stop("SIGTERM"));

  await startServer(bot);
  console.log("Bot started");
}

main().catch((error) => {
  console.error("Failed to start application", error);
  process.exit(1);
});
